<script setup lang="ts">
import { router, useForm } from '@inertiajs/vue3';
import TextField from '@/components/forms/TextField.vue';
import { useTrans } from '@/composables/useTrans';
import AuthLayout from '@/layouts/AuthLayout.vue';

/**
 * Mandatory setup of the second factor (D-136, M01-CA1): until a code is confirmed every page
 * of the portal leads here. QR code and key are generated by the server; the recovery codes
 * are shown on the next page, once.
 */
const props = defineProps<{
    /** SVG of the QR code as a data URI, generated by the server. */
    qrCode: string;
    /** Same key in groups of four characters, for manual entry. */
    secret: string;
    account: string;
    confirmUrl: string;
    logoutUrl: string;
}>();

const { t } = useTrans();

const form = useForm({ code: '' });

function submit(): void {
    form.transform((data) => ({ code: data.code.replace(/\s+/g, '') }))
        .post(props.confirmUrl, { onFinish: () => form.reset() });
}

function logout(): void {
    router.post(props.logoutUrl);
}
</script>

<template>
    <AuthLayout
        :title="t('auth.setup.title')"
        wide
    >
        <p class="mt-2 text-sm leading-relaxed text-muted">
            {{ t('auth.setup.intro') }}
        </p>

        <ol class="mt-6 flex flex-col gap-5 text-sm leading-relaxed">
            <li class="flex gap-3">
                <span class="flex size-6 shrink-0 items-center justify-center rounded-full bg-navy text-xs font-semibold text-white">1</span>
                <div class="flex min-w-0 flex-1 flex-col gap-3">
                    <p>{{ t('auth.setup.step_scan') }}</p>
                    <img
                        :src="qrCode"
                        :alt="t('auth.setup.qr_alt')"
                        width="192"
                        height="192"
                        class="size-48 rounded-lg border border-line bg-white p-2"
                    >
                    <p>{{ t('auth.setup.step_key') }}</p>
                    <code class="block rounded-lg bg-surface px-3 py-2.5 font-mono text-[15px] tracking-wider break-all select-all">{{ secret }}</code>
                    <p class="text-[13px] text-muted">
                        {{ t('auth.setup.account', { account }) }}
                    </p>
                </div>
            </li>
            <li class="flex gap-3">
                <span class="flex size-6 shrink-0 items-center justify-center rounded-full bg-navy text-xs font-semibold text-white">2</span>
                <form
                    class="flex min-w-0 flex-1 flex-col gap-4"
                    novalidate
                    @submit.prevent="submit"
                >
                    <p>{{ t('auth.setup.step_confirm') }}</p>
                    <TextField
                        v-model="form.code"
                        :label="t('auth.setup.code')"
                        inputmode="numeric"
                        autocomplete="one-time-code"
                        :error="form.errors.code"
                        mono
                    />
                    <button
                        type="submit"
                        class="inline-flex min-h-11 items-center justify-center rounded-[10px] bg-accent px-5 text-[15px] font-semibold text-white hover:bg-accent-strong focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent disabled:cursor-not-allowed disabled:opacity-60"
                        :disabled="form.processing"
                    >
                        {{ form.processing ? t('auth.setup.submitting') : t('auth.setup.submit') }}
                    </button>
                </form>
            </li>
        </ol>

        <div class="mt-6 border-t border-line pt-4">
            <button
                type="button"
                class="inline-flex min-h-11 items-center text-sm text-muted underline-offset-2 hover:underline focus-visible:outline-2 focus-visible:outline-accent"
                @click="logout"
            >
                {{ t('auth.setup.logout') }}
            </button>
        </div>
    </AuthLayout>
</template>
